  /// Puzzles added at run time — the Daily pool, loaded from a bundled asset
  /// rather than compiled in. Registering them here lets the whole game
  /// pipeline (lookup, solution validation, archive) treat a daily puzzle
  /// exactly like a built-in one.
  static final Map<String, PuzzleData> _runtime = {};

  static void registerRuntime(PuzzleData puzzle) {
    _runtime[puzzle.id] = puzzle;
  }

